// [rms, amp_1x, amp_2x, amp_3.5x, amp_0.5x] — one pattern per machine state.
const states = [
    { name: 'healthy', features: [0.15, 0.05, 0.03, 0.02, 0.02] },
    { name: 'imbalance', features: [0.6, 0.9, 0.1, 0.05, 0.05] },
    { name: 'misalignment', features: [0.6, 0.4, 0.9, 0.05, 0.05] },
    { name: 'bearing', features: [0.85, 0.1, 0.1, 0.95, 0.1] },
    { name: 'looseness', features: [0.6, 0.3, 0.2, 0.1, 0.9] }
];
// Hold each state for five ticks, then move on.
const tick = context.get('tick') || 0;
context.set('tick', tick + 1);
const state = states[Math.floor(tick / 5) % states.length];
msg.payload = state.features;
msg.simulatedState = state.name;
msg.topic = 'machine-a/features';
return msg;

const labels = ['healthy', 'imbalance', 'misalignment', 'bearing', 'looseness'];
const scores = Array.from(msg.prediction || []);
if (scores.length !== labels.length) { return null; }
let best = 0;
for (let i = 1; i < scores.length; i++) { if (scores[i] > scores[best]) { best = i; } }
msg.payload = { fault: labels[best], simulated: msg.simulatedState, scores: scores };
return msg;
